var a=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<VRC.SDK3.Avatars.Components.VRCAvatarDescriptor>(true)).Single(a=>a.name=="MANUKA_lilToon");
var animator=a.GetComponent<UnityEngine.Animator>();var r=a.GetComponentsInChildren<UnityEngine.SkinnedMeshRenderer>(true).Single(r=>r.name=="Manuka_body");
var mesh=new UnityEngine.Mesh();r.BakeMesh(mesh,true);
try {
var bone=animator.GetBoneTransform(UnityEngine.HumanBodyBones.LeftFoot);var totals=r.sharedMesh.GetBonesPerVertex();var weights=r.sharedMesh.GetAllBoneWeights();var vertices=mesh.vertices;int index=0;var points=new System.Collections.Generic.List<UnityEngine.Vector3>();
for(int i=0;i<totals.Length;i++){float sum=0;for(int j=0;j<totals[i];j++){var w=weights[index++];var b=r.bones[w.boneIndex];if(b!=null&&(b==bone||b.IsChildOf(bone)))sum+=w.weight;}if(sum>.5f)points.Add(r.transform.position+r.transform.rotation*vertices[i]);}
return new {bones=new[]{UnityEngine.HumanBodyBones.Hips,UnityEngine.HumanBodyBones.LeftUpperLeg,UnityEngine.HumanBodyBones.LeftFoot,UnityEngine.HumanBodyBones.LeftToes}.Select(b=>new{name=b.ToString(),position=animator.GetBoneTransform(b)?.position.ToString("F5")}).ToArray(),footCount=points.Count,footMin=new UnityEngine.Vector3(points.Min(p=>p.x),points.Min(p=>p.y),points.Min(p=>p.z)).ToString("F5"),footMax=new UnityEngine.Vector3(points.Max(p=>p.x),points.Max(p=>p.y),points.Max(p=>p.z)).ToString("F5"),blendshapes=Enumerable.Range(0,r.sharedMesh.blendShapeCount).Where(i=>r.GetBlendShapeWeight(i)!=0||r.sharedMesh.GetBlendShapeName(i).ToLower().Contains("open")).Select(i=>new{name=r.sharedMesh.GetBlendShapeName(i),weight=r.GetBlendShapeWeight(i)}).ToArray()};
}finally{UnityEngine.Object.DestroyImmediate(mesh);}
